{"path":"/workspace/rust/colors.rs","command":"create","file_text":"//! picocolors-compatible terminal styling.

use std::env;
use std::io::IsTerminal;

fn color_enabled() -> bool {
    let args: Vec<String> = env::args().collect();
    if env::var_os("NO_COLOR").is_some() || args.iter().any(|a| a == "--no-color") {
        return false;
    }
    env::var_os("FORCE_COLOR").is_some()
        || args.iter().any(|a| a == "--color")
        || cfg!(windows)
        || (std::io::stdout().is_terminal()
            && env::var("TERM").ok().as_deref() != Some("dumb"))
        || env::var_os("CI").is_some()
}

fn wrap(enabled: bool, open: &str, close: &str, input: &str) -> String {
    if !enabled {
        return input.to_string();
    }
    format!("{open}{input}{close}")
}

#[derive(Clone, Copy)]
pub struct Colors {
    enabled: bool,
}

impl Colors {
    pub fn new() -> Self {
        Self {
            enabled: color_enabled(),
        }
    }

    pub fn red(&self, s: &str) -> String {
        wrap(self.enabled, "\u{1b}[31m", "\u{1b}[39m", s)
    }
    pub fn green(&self, s: &str) -> String {
        wrap(self.enabled, "\u{1b}[32m", "\u{1b}[39m", s)
    }
    pub fn yellow(&self, s: &str) -> String {
        wrap(self.enabled, "\u{1b}[33m", "\u{1b}[39m", s)
    }
    pub fn blue(&self, s: &str) -> String {
        wrap(self.enabled, "\u{1b}[34m", "\u{1b}[39m", s)
    }
    pub fn white(&self, s: &str) -> String {
        wrap(self.enabled, "\u{1b}[37m", "\u{1b}[39m", s)
    }
    pub fn bg_red(&self, s: &str) -> String {
        wrap(self.enabled, "\u{1b}[41m", "\u{1b}[49m", s)
    }
    pub fn bg_green(&self, s: &str) -> String {
        wrap(self.enabled, "\u{1b}[42m", "\u{1b}[49m", s)
    }
    pub fn bg_yellow(&self, s: &str) -> String {
        wrap(self.enabled, "\u{1b}[43m", "\u{1b}[49m", s)
    }
    pub fn bg_blue(&self, s: &str) -> String {
        wrap(self.enabled, "\u{1b}[44m", "\u{1b}[49m", s)
    }
}

impl Default for Colors {
    fn default() -> Self {
        Self::new()
    }
}
