{"path":"/workspace/rust/match_node.rs","command":"create","file_text":"//! Port of `src/matchNode.js`.
//!
//! Needle functions cannot be represented in Rust values; callers that need
//! predicate matching keep using the JavaScript implementation via the bridge.

use serde_json::Value;

pub fn match_node(haystack: &Value, needle: &Value) -> bool {
    if is_node(needle) && is_node(haystack) {
        if let Value::Object(obj) = needle {
            return obj.iter().all(|(property, expected)| {
                haystack
                    .as_object()
                    .map(|h| h.contains_key(property) && match_node(&h[property], expected))
                    .unwrap_or(false)
            });
        }
    }
    haystack == needle
}

fn is_node(value: &Value) -> bool {
    value.is_object() || value.is_array()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn matches_subset_object() {
        assert!(match_node(
            &json!({"type": "Identifier", "name": "foo", "extra": 1}),
            &json!({"type": "Identifier", "name": "foo"})
        ));
        assert!(!match_node(
            &json!({"type": "Identifier", "name": "foo"}),
            &json!({"type": "Identifier", "name": "bar"})
        ));
    }
}
"}

{"path":"/workspace/rust/ignore.rs","command":"create","file_text":"//! Port of `src/ignoreFiles.js`.

use std::fs;
use std::io;
use std::path::Path;

use globset::{GlobBuilder, GlobSet, GlobSetBuilder};

#[derive(Default)]
pub struct IgnoreMatcher {
    patterns: Vec<String>,
    set: Option<GlobSet>,
}

impl IgnoreMatcher {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add(&mut self, input: impl IntoIterator<Item = impl AsRef<str>>) {
        for val in input {
            self.add_ignore_pattern(val.as_ref());
        }
        self.rebuild();
    }

    pub fn add_from_file(&mut self, input: impl IntoIterator<Item = impl AsRef<Path>>) -> io::Result<()> {
        for config in input {
            let path = config.as_ref();
            let stats = fs::metadata(path)?;
            if stats.is_file() {
                let content = fs::read_to_string(path)?;
                for line in content.split(['\n', '\r']) {
                    if line.is_empty() {
                        continue;
                    }
                    self.add_ignore_pattern(line);
                }
            }
        }
        self.rebuild();
        Ok(())
    }

    fn add_ignore_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let pattern = val.to_string();
        if !pattern.contains('/') {
            self.patterns.push(format!("**/{pattern}"));
        } else if pattern.ends_with('/') {
            self.patterns.push(format!("**/{pattern}**"));
            self.patterns.push(format!("{pattern}**"));
        }
        self.patterns.push(pattern);
    }

    fn rebuild(&mut self) {
        if self.patterns.is_empty() {
            self.set = None;
            return;
        }
        let mut builder = GlobSetBuilder::new();
        for pattern in &self.patterns {
            if let Ok(glob) = GlobBuilder::new(pattern)
                .literal_separator(true)
                .build()
            {
                builder.add(glob);
            }
        }
        self.set = builder.build().ok();
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        let Some(set) = &self.set else {
            return false;
        };
        if set.is_match(path) {
            return true;
        }
        let normalized = strip_traversal_prefix(path);
        normalized != path && set.is_match(normalized)
    }
}

fn strip_traversal_prefix(path: &str) -> &str {
    let bytes = path.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'.' && i + 1 < bytes.len() && (bytes[i + 1] == b'/' || bytes[i + 1] == b'\\')
        {
            i += 2;
            continue;
        }
        if bytes[i] == b'.'
            && i + 2 < bytes.len()
            && bytes[i + 1] == b'.'
            && (bytes[i + 2] == b'/' || bytes[i + 2] == b'\\')
        {
            i += 3;
            continue;
        }
        break;
    }
    &path[i..]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ignores_glob_and_stripped_relative_prefix() {
        let mut ign = IgnoreMatcher::new();
        ign.add(["**/node_modules/**"]);
        assert!(ign.should_ignore("app/node_modules/pkg/index.js"));
        assert!(ign.should_ignore("../app/node_modules/pkg/index.js"));
        assert!(!ign.should_ignore("app/src/index.js"));
    }
}
"}

{"path":"/workspace/rust/package.rs","command":"create","file_text":"//! Port of `utils/requirePackage.js` plus version-string helpers.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

pub const JSCODESHIFT_VERSION: &str = env!("CARGO_PKG_VERSION");

/// Walk parents of a resolved package entry looking for a matching package.json.
pub fn require_package(name: &str, start: &Path) -> Option<serde_json::Value> {
    let mut dir = start.to_path_buf();
    if dir.is_file() {
        dir.pop();
    }
    loop {
        let pkg_path = dir.join("package.json");
        if let Ok(content) = fs::read_to_string(&pkg_path) {
            if let Ok(pkg) = serde_json::from_str::<serde_json::Value>(&content) {
                if pkg.get("name").and_then(|v| v.as_str()) == Some(name) {
                    return Some(pkg);
                }
            }
        }
        if !dir.pop() {
            break;
        }
        if dir.as_os_str() == "/" || dir.as_os_str().is_empty() {
            if let Ok(content) = fs::read_to_string(dir.join("package.json")) {
                if let Ok(pkg) = serde_json::from_str::<serde_json::Value>(&content) {
                    if pkg.get("name").and_then(|v| v.as_str()) == Some(name) {
                        return Some(pkg);
                    }
                }
            }
            break;
        }
    }
    None
}

fn node_require_resolve(name: &str, from_dir: &Path) -> Option<PathBuf> {
    let script = format!("process.stdout.write(require.resolve({name:?}))");
    let output = Command::new("node")
        .arg("-e")
        .arg(script)
        .current_dir(from_dir)
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let path = String::from_utf8_lossy(&output.stdout).trim().to_string();
    if path.is_empty() {
        None
    } else {
        Some(PathBuf::from(path))
    }
}

fn package_version(name: &str, from_dir: &Path) -> String {
    if let Some(entry) = node_require_resolve(name, from_dir) {
        if let Some(pkg) = require_package(name, &entry) {
            if let Some(v) = pkg.get("version").and_then(|v| v.as_str()) {
                return v.to_string();
            }
        }
    }
    String::new()
}

fn babel_core_version(from_dir: &Path) -> String {
    let script = "process.stdout.write(require('@babel/core').version)";
    let output = Command::new("node")
        .arg("-e")
        .arg(script)
        .current_dir(from_dir)
        .output();
    match output {
        Ok(out) if out.status.success() => String::from_utf8_lossy(&out.stdout).trim().to_string(),
        _ => String::new(),
    }
}

pub fn version_text(from_dir: &Path) -> String {
    let babel = babel_core_version(from_dir);
    let babylon = package_version("@babel/parser", from_dir);
    let flow = package_version("flow-parser", from_dir);
    let recast = package_version("recast", from_dir);
    format!(
        "jscodeshift: {JSCODESHIFT_VERSION}\n - babel: {babel}\n - babylon: {babylon}\n - flow: {flow}\n - recast: {recast}\n"
    )
}

/// Babel DEFAULT_EXTENSIONS plus ts/tsx, stripped of leading dots, sorted, joined.
pub fn default_extensions() -> String {
    let mut exts = vec!["js", "jsx", "es6", "es", "mjs", "cjs", "ts", "tsx"];
    exts.sort_unstable();
    exts.join(",")
}

pub fn package_root() -> PathBuf {
    if let Ok(exe) = std::env::current_exe() {
        // target/release/jscodeshift or target/debug/jscodeshift
        if let Some(dir) = exe.parent() {
            // Prefer walking up until we see package.json + rust/ or index.js.
            let mut cur = dir.to_path_buf();
            for _ in 0..6 {
                if cur.join("package.json").exists() && cur.join("index.js").exists() {
                    return cur;
                }
                if !cur.pop() {
                    break;
                }
            }
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        if cwd.join("package.json").exists() && cwd.join("index.js").exists() {
            return cwd;
        }
    }
    // Fall back to CARGO_MANIFEST_DIR at compile time.
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}
"}

{"path":"/workspace/rust/args.rs","command":"create","file_text":"//! Port of `src/argsParser.js` plus the CLI option table from `bin/jscodeshift.js`.

use std::collections::BTreeMap;
use std::fmt;
use std::fs;

use serde_json::Value;

use crate::package::{default_extensions, version_text};

const MISSING: &str = "__jscodeshift_missing_value__";

#[derive(Debug, Clone)]
pub struct ParseError {
    pub exit_code: i32,
    pub message: String,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

impl std::error::Error for ParseError {}

#[derive(Debug, Clone)]
pub struct ParseResult {
    pub positional_arguments: Vec<Value>,
    pub options: BTreeMap<String, Value>,
}

#[derive(Clone)]
struct OptionDef {
    key: String,
    full: String,
    abbr: Option<String>,
    flag: bool,
    list: bool,
    default: Option<Value>,
    default_help: Option<String>,
    choices: Option<Vec<Value>>,
    help: Option<String>,
    metavar: Option<String>,
    display_index: i32,
    callback: Option<CallbackKind>,
    process: Option<ProcessKind>,
}

#[derive(Clone, Copy)]
enum CallbackKind {
    Help,
    Version,
}

#[derive(Clone, Copy)]
enum ProcessKind {
    Number,
    ParserConfig,
}

#[derive(Clone)]
struct Prepared {
    by_flag: BTreeMap<String, OptionDef>,
    defs: Vec<OptionDef>,
}

fn is_option(value: &str) -> bool {
    value.starts_with('-') && value != "-" && value != "--"
}

fn format_option(option: &OptionDef) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = &option.abbr {
        text.push('-');
        text.push_str(abbr);
        text.push_str(", ");
    } else {
        text.push_str("    ");
    }
    text.push_str("--");
    if option.flag {
        text.push_str("(no-)");
    }
    text.push_str(&option.full);
    if let Some(choices) = &option.choices {
        text.push('=');
        let joined = choices
            .iter()
            .map(value_to_display)
            .collect::<Vec<_>>()
            .join("|");
        text.push_str(&joined);
    } else if let Some(metavar) = &option.metavar {
        text.push('=');
        text.push_str(metavar);
    }
    if option.list {
        text.push_str(" ...");
    }
    if option.default_help.is_some() || option.default.is_some() || option.help.is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            text.push_str(&" ".repeat(32 - text.len()));
        }
        let text_length = text.len();
        if let Some(help) = &option.help {
            text.push_str(help);
        }
        if option.default_help.is_some() || option.default.is_some() {
            if option.help.is_some() {
                text.push('\n');
            }
            text.push_str(&" ".repeat(text_length));
            let default_disp = option
                .default_help
                .clone()
                .or_else(|| option.default.as_ref().map(value_to_display))
                .unwrap_or_default();
            text.push_str(&format!("(default: {default_disp})"));
        }
    }
    text
}

fn value_to_display(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        Value::Null => "null".to_string(),
        other => other.to_string(),
    }
}

pub fn get_help_text() -> String {
    let defs = cli_option_defs();
    let mut opts = defs;
    opts.sort_by_key(|o| o.display_index);
    let body = opts.iter().map(format_option).collect::<Vec<_>>().join("\n");
    let text = format!(
        "
Usage: jscodeshift [OPTION]... PATH...
  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...
  or:  jscodeshift [OPTION]... -t URL PATH...
  or:  jscodeshift [OPTION]... --stdin < file_list.txt

Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.
If --stdin is set, each line of the standard input is used as a path.

Options:
\"...\" behind an option means that it can be supplied multiple times.
All options are also passed to the transformer, which means you can supply custom options that are not listed here.

{body}
"
    );
    // JS String.prototype.trimLeft
    text.trim_start_matches([' ', '\t', '\n', '\r']).to_string()
}

fn throw_error(exit_code: i32, message: String, with_help: bool) -> ParseError {
    let message = if with_help {
        format!("{message}\n\n---\n\n{}", get_help_text())
    } else {
        message
    };
    ParseError { exit_code, message }
}

fn prepare_options() -> Prepared {
    let mut defs = cli_option_defs();
    let mut by_flag = BTreeMap::new();
    for option in &defs {
        by_flag.insert(format!("--{}", option.full), option.clone());
        if let Some(abbr) = &option.abbr {
            by_flag.insert(format!("-{abbr}"), option.clone());
        }
        if option.flag {
            by_flag.insert(format!("--no-{}", option.full), option.clone());
        }
    }
    // keep defs for defaults
    let _ = &mut defs;
    Prepared { by_flag, defs }
}

fn json_parse_or_string(value: &str) -> Value {
    match serde_json::from_str::<Value>(value) {
        Ok(v) => v,
        Err(_) => Value::String(value.to_string()),
    }
}

fn apply_process(kind: ProcessKind, value: &str) -> Result<Value, ParseError> {
    match kind {
        ProcessKind::Number => {
            // JS Number(value) — empty string is 0, non-numeric is NaN
            if value.is_empty() {
                return Ok(Value::Number(0.into()));
            }
            if let Ok(n) = value.parse::<i64>() {
                return Ok(Value::Number(n.into()));
            }
            if let Ok(n) = value.parse::<f64>() {
                if let Some(num) = serde_json::Number::from_f64(n) {
                    return Ok(Value::Number(num));
                }
            }
            // Preserve JS Number("foo") === NaN by storing null-like; validation for
            // verbose will fail if used there. For cpus we later treat non-numbers as 0.
            Ok(Value::Null)
        }
        ProcessKind::ParserConfig => {
            let content = fs::read_to_string(value).map_err(|e| ParseError {
                exit_code: 1,
                message: e.to_string(),
            })?;
            serde_json::from_str(&content).map_err(|e| ParseError {
                exit_code: 1,
                message: e.to_string(),
            })
        }
    }
}

fn value_in_choices(value: &Value, choices: &[Value]) -> bool {
    choices.iter().any(|c| values_equal_js(c, value))
}

fn values_equal_js(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(n), Value::String(s)) | (Value::String(s), Value::Number(n)) => {
            s == &n.to_string()
        }
        _ => a == b,
    }
}

pub fn parse(args: &[String]) -> Result<ParseResult, ParseError> {
    let prepared = prepare_options();
    let mut parsed: BTreeMap<String, Value> = BTreeMap::new();
    let mut positional: Vec<Value> = Vec::new();

    for option in &prepared.defs {
        if let Some(default) = &option.default {
            parsed.insert(option.key.clone(), default.clone());
        } else if option.list {
            parsed.insert(option.key.clone(), Value::Array(vec![]));
        }
    }

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if is_option(arg) {
            let mut option_name = arg.clone();
            let mut value: Option<String> = None;
            if let Some(index) = arg.find('=') {
                option_name = arg[..index].to_string();
                value = Some(arg[index + 1..].to_string());
            }

            let mut option = prepared.by_flag.get(&option_name).cloned();
            if option.is_none() {
                // Unknown options are passed along.
                let real_option_name = option_name
                    .trim_start_matches('-')
                    .strip_prefix("no-")
                    .unwrap_or_else(|| option_name.trim_start_matches('-'))
                    .to_string();
                // JS: optionName.replace(/^--?(no-)?/, '')
                let real_option_name = strip_unknown_name(&option_name);
                let existing = parsed.get(&real_option_name);
                let is_list = existing.is_some() && existing != Some(&Value::Bool(true));
                let next_is_option = args.get(i + 1).map(|s| is_option(s)).unwrap_or(false);
                let flag = existing.is_none() && value.is_none() && next_is_option;

                let unknown = OptionDef {
                    key: real_option_name.clone(),
                    full: real_option_name.clone(),
                    abbr: None,
                    flag,
                    list: is_list,
                    default: None,
                    default_help: None,
                    choices: None,
                    help: None,
                    metavar: None,
                    display_index: 0,
                    callback: None,
                    process: None,
                };

                if is_list {
                    if let Some(current) = parsed.get(&real_option_name).cloned() {
                        if !current.is_array() {
                            if current == Value::Bool(true) {
                                parsed.insert(real_option_name.clone(), Value::Array(vec![]));
                            } else {
                                parsed.insert(real_option_name.clone(), Value::Array(vec![current]));
                            }
                        }
                    }
                }
                let _ = real_option_name;
                option = Some(unknown);
            }

            let option = option.unwrap();
            if let Some(cb) = option.callback {
                let message = match cb {
                    CallbackKind::Help => get_help_text(),
                    CallbackKind::Version => version_text(&crate::package::package_root()),
                };
                return Err(throw_error(0, message, false));
            } else if option.flag {
                let parsed_value = if option_name.starts_with("--no-") {
                    Value::Bool(false)
                } else if let Some(v) = &value {
                    Value::Bool(v == "1")
                } else {
                    Value::Bool(true)
                };
                parsed.insert(option.key.clone(), parsed_value);
            } else {
                if value.is_none() && i < args.len() - 1 && !is_option(&args[i + 1]) {
                    value = Some(args[i + 1].clone());
                    i += 1;
                }
                if let Some(v) = value {
                    let mut processed = if let Some(kind) = option.process {
                        apply_process(kind, &v)?
                    } else if prepared.by_flag.contains_key(&format!("--{}", option.full))
                        && option.process.is_none()
                        && option.callback.is_none()
                        && !is_builtin_key(&option.key)
                    {
                        json_parse_or_string(&v)
                    } else if !is_builtin_key(&option.key) {
                        json_parse_or_string(&v)
                    } else {
                        Value::String(v)
                    };
                    // Unknown options always JSON.parse
                    if !is_builtin_key(&option.key) {
                        if let Value::String(s) = &processed {
                            processed = json_parse_or_string(s);
                        }
                    }
                    if option.list {
                        parsed
                            .entry(option.key.clone())
                            .or_insert_with(|| Value::Array(vec![]));
                        if let Some(Value::Array(arr)) = parsed.get_mut(&option.key) {
                            arr.push(processed);
                        }
                    } else {
                        parsed.insert(option.key, processed);
                    }
                } else {
                    parsed.insert(option.key, Value::String(MISSING.to_string()));
                }
            }
        } else if arg.chars().all(|c| c.is_ascii_digit()) && !arg.is_empty() {
            let n: i64 = arg.parse().unwrap_or(0);
            positional.push(Value::Number(n.into()));
        } else {
            positional.push(Value::String(arg.clone()));
        }
        i += 1;
    }

    for (name, value) in &parsed {
        if value.as_str() == Some(MISSING) {
            let full = prepared
                .defs
                .iter()
                .find(|d| d.key == *name)
                .map(|d| d.full.clone())
                .unwrap_or_else(|| name.clone());
            return Err(throw_error(
                1,
                format!("Missing value: --{full} requires a value"),
                true,
            ));
        }
    }

    validate_options(&parsed, &prepared.defs)?;

    Ok(ParseResult {
        positional_arguments: positional,
        options: parsed,
    })
}

fn is_builtin_key(key: &str) -> bool {
    matches!(
        key,
        "transform"
            | "cpus"
            | "verbose"
            | "dry"
            | "print"
            | "babel"
            | "extensions"
            | "ignorePattern"
            | "ignoreConfig"
            | "gitignore"
            | "runInBand"
            | "silent"
            | "parser"
            | "parserConfig"
            | "failOnError"
            | "version"
            | "stdin"
            | "help"
    )
}

fn strip_unknown_name(option_name: &str) -> String {
    // JS: optionName.replace(/^--?(no-)?/, '')
    let mut s = option_name;
    if let Some(rest) = s.strip_prefix("--") {
        s = rest;
    } else if let Some(rest) = s.strip_prefix('-') {
        s = rest;
    }
    if let Some(rest) = s.strip_prefix("no-") {
        s = rest;
    }
    s.to_string()
}

fn validate_options(parsed: &BTreeMap<String, Value>, defs: &[OptionDef]) -> Result<(), ParseError> {
    let mut errors = Vec::new();
    for option in defs {
        if let Some(choices) = &option.choices {
            if let Some(val) = parsed.get(&option.key) {
                if !value_in_choices(val, choices) {
                    let joined = choices
                        .iter()
                        .map(value_to_display)
                        .collect::<Vec<_>>()
                        .join(",");
                    errors.push(format!(
                        "Error: --{} must be one of the values {joined}",
                        option.full
                    ));
                }
            }
        }
    }
    if !errors.is_empty() {
        return Err(throw_error(1, errors.join("\n"), true));
    }
    Ok(())
}

