{"path":"/workspace/rust/discover.rs","command":"create","file_text":"//! File discovery ported from `src/Runner.js`.

use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};

use crate::ignore::IgnoreMatcher;

pub fn get_all_files(
    paths: &[String],
    extensions: Option<&[String]>,
    ignores: &IgnoreMatcher,
) -> io::Result<Vec<String>> {
    let mut out = Vec::new();
    for file in paths {
        match collect_one(file, extensions, ignores) {
            Ok(mut files) => out.append(&mut files),
            Err(err) if err.kind() == io::ErrorKind::NotFound => {
                let mut stderr = io::stderr().lock();
                let _ = write!(stderr, "Skipping path {file} which does not exist. \n");
            }
            Err(err) => {
                // lstat errors other than not-found are treated like missing paths
                // in the original runner (any err => skip).
                let _ = err;
                let mut stderr = io::stderr().lock();
                let _ = write!(stderr, "Skipping path {file} which does not exist. \n");
            }
        }
    }
    Ok(out)
}

fn matches_extension(name: &str, extensions: Option<&[String]>) -> bool {
    let Some(exts) = extensions else {
        return true;
    };
    let ext = Path::new(name)
        .extension()
        .and_then(|e| e.to_str())
        .map(|e| format!(".{e}"))
        .unwrap_or_default();
    exts.iter().any(|e| e == &ext)
}

fn collect_one(
    file: &str,
    extensions: Option<&[String]>,
    ignores: &IgnoreMatcher,
) -> io::Result<Vec<String>> {
    let meta = fs::symlink_metadata(file)?;
    if meta.is_dir() {
        let mut files = Vec::new();
        dir_files(Path::new(file), ignores, &mut files)?;
        files.retain(|name| matches_extension(name, extensions));
        Ok(files)
    } else if !matches_extension(file, extensions) || ignores.should_ignore(file) {
        Ok(vec![])
    } else {
        Ok(vec![file.to_string()])
    }
}

fn dir_files(dir: &Path, ignores: &IgnoreMatcher, files: &mut Vec<String>) -> io::Result<()> {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(err) => return Err(err),
    };
    let mut names: Vec<PathBuf> = Vec::new();
    for entry in entries {
        match entry {
            Ok(ent) => names.push(ent.path()),
            Err(_) => {}
        }
    }
    for name in names {
        let name_str = path_to_string(&name);
        match fs::metadata(&name) {
            Err(_) => {
                let mut stdout = io::stdout().lock();
                let _ = write!(
                    stdout,
                    "Skipping path \"{name_str}\" which does not exist.\n"
                );
            }
            Ok(stats) => {
                if ignores.should_ignore(&name_str) {
                    continue;
                } else if stats.is_dir() {
                    // Original concatenates '/' so the recursive listing uses a trailing slash.
                    dir_files(&name, ignores, files)?;
                } else {
                    files.push(name_str);
                }
            }
        }
    }
    Ok(())
}

fn path_to_string(path: &Path) -> String {
    path.to_string_lossy().into_owned()
}
"}

{"path":"/workspace/rust/worker.rs","command":"create","file_text":"//! Worker process management. Transform execution lives in the JS bridge.

use std::io::{BufRead, BufReader, Write};
use std::path::Path;
use std::process::{Child, ChildStdin, Command, Stdio};

use serde::{Deserialize, Serialize};
use serde_json::Value;

#[derive(Debug, Deserialize)]
#[serde(tag = "action")]
pub enum WorkerMessage {
    #[serde(rename = "status")]
    Status { status: String, msg: String },
    #[serde(rename = "update")]
    Update { name: String, quantity: f64 },
    #[serde(rename = "free")]
    Free,
    #[serde(rename = "report")]
    Report { file: String, msg: String },
    #[serde(rename = "print")]
    Print { text: String },
}

#[derive(Serialize)]
struct WorkerJob<'a> {
    files: &'a [String],
    options: &'a Value,
}

pub struct Worker {
    child: Child,
    stdin: Option<ChildStdin>,
    stdout: BufReader<std::process::ChildStdout>,
}

impl Worker {
    pub fn spawn(host: &Path, transform: &str, use_babel: bool, package_root: &Path) -> std::io::Result<Self> {
        let babel = if use_babel { "babel" } else { "no-babel" };
        let mut cmd = Command::new("node");
        cmd.arg(host)
            .arg(transform)
            .arg(babel)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .current_dir(std::env::current_dir()?);

        // Ensure the public package and its deps resolve from the install root.
        let mut node_path = package_root.join("node_modules").display().to_string();
        if let Ok(existing) = std::env::var("NODE_PATH") {
            if !existing.is_empty() {
                node_path = format!("{node_path}:{existing}");
            }
        }
        cmd.env("NODE_PATH", node_path);
        cmd.env("JSCODESHIFT_ROOT", package_root);

        let mut child = cmd.spawn()?;
        let stdin = child.stdin.take();
        let stdout = BufReader::new(child.stdout.take().expect("stdout piped"));
        Ok(Self {
            child,
            stdin,
            stdout,
        })
    }

    pub fn send_job(&mut self, files: &[String], options: &Value) -> std::io::Result<()> {
        let job = WorkerJob { files, options };
        let mut line = serde_json::to_string(&job).map_err(|e| {
            std::io::Error::new(std::io::ErrorKind::InvalidData, e)
        })?;
        line.push('\n');
        if let Some(stdin) = self.stdin.as_mut() {
            stdin.write_all(line.as_bytes())?;
            stdin.flush()?;
        }
        Ok(())
    }

    pub fn recv(&mut self) -> std::io::Result<Option<WorkerMessage>> {
        let mut line = String::new();
        let n = self.stdout.read_line(&mut line)?;
        if n == 0 {
            return Ok(None);
        }
        let msg: WorkerMessage = serde_json::from_str(line.trim_end()).map_err(|e| {
            std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                format!("invalid worker message: {e}: {line}"),
            )
        })?;
        Ok(Some(msg))
    }

    pub fn wait(&mut self) -> std::io::Result<()> {
        // Close stdin so the host can exit if it is blocking on read.
        self.stdin.take();
        self.child.wait()?;
        Ok(())
    }
}

impl Drop for Worker {
    fn drop(&mut self) {
        let _ = self.child.kill();
    }
}
"}

