{"path":"/workspace/rust/runner.rs","command":"create","file_text":"//! Port of `src/Runner.js`.

use std::collections::BTreeMap;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::{Arc, Mutex};
use std::time::Instant;

use serde_json::{json, Value};

use crate::args::{bool_opt, number_opt, string_list, string_opt};
use crate::colors::Colors;
use crate::discover::get_all_files;
use crate::ignore::IgnoreMatcher;
use crate::package::package_root;
use crate::worker::{Worker, WorkerMessage};

const CHUNK_SIZE: usize = 50;

#[derive(Debug, Default, Clone)]
pub struct FileCounters {
    pub error: u64,
    pub ok: u64,
    pub nochange: u64,
    pub skip: u64,
}

#[derive(Clone)]
pub struct RunOptions {
    pub transform: String,
    pub paths: Vec<String>,
    pub options: BTreeMap<String, Value>,
}

pub fn available_cpus() -> usize {
    let n = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1);
    n.saturating_sub(1).max(1)
}

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{s}\n")
    }
}

fn write_stdout(msg: &str) {
    let mut out = io::stdout().lock();
    let _ = out.write_all(msg.as_bytes());
    let _ = out.flush();
}

fn write_stderr(msg: &str) {
    let mut out = io::stderr().lock();
    let _ = out.write_all(msg.as_bytes());
    let _ = out.flush();
}

struct Logger {
    colors: Colors,
}

impl Logger {
    fn new() -> Self {
        Self {
            colors: Colors::new(),
        }
    }

    fn ok(&self, msg: &str, verbose: i64) {
        if verbose >= 2 {
            write_stdout(&format!(
                "{}{msg}",
                self.colors.bg_green(&self.colors.white(" OKK "))
            ));
        }
    }
    fn nochange(&self, msg: &str, verbose: i64) {
        if verbose >= 1 {
            write_stdout(&format!(
                "{}{msg}",
                self.colors.bg_yellow(&self.colors.white(" NOC "))
            ));
        }
    }
    fn skip(&self, msg: &str, verbose: i64) {
        if verbose >= 1 {
            write_stdout(&format!(
                "{}{msg}",
                self.colors.bg_yellow(&self.colors.white(" SKIP "))
            ));
        }
    }
    fn error(&self, msg: &str, verbose: i64) {
        if verbose >= 0 {
            write_stdout(&format!(
                "{}{msg}",
                self.colors.bg_red(&self.colors.white(" ERR "))
            ));
        }
    }

    fn status(&self, status: &str, msg: &str, verbose: i64) {
        match status {
            "ok" => self.ok(msg, verbose),
            "nochange" => self.nochange(msg, verbose),
            "skip" => self.skip(msg, verbose),
            "error" => self.error(msg, verbose),
            _ => {}
        }
    }

    fn report(&self, file: &str, msg: &str) {
        write_stdout(&line_break(&format!(
            "{}{file} {msg}",
            self.colors.bg_blue(&self.colors.white(" REP "))
        )));
    }

    fn missing_transform(&self, path: &str) {
        write_stderr(&format!(
            "{} Transform file {path} does not exist \n",
            self.colors.bg_red(&self.colors.white("ERROR"))
        ));
    }

    fn show_file_stats(&self, c: &FileCounters) {
        write_stdout(&format!(
            "Results: \n{}{}{}{}",
            self.colors.red(&format!("{} errors\n", c.error)),
            self.colors.yellow(&format!("{} unmodified\n", c.nochange)),
            self.colors.yellow(&format!("{} skipped\n", c.skip)),
            self.colors.green(&format!("{} ok\n", c.ok)),
        ));
    }

    fn show_stats(&self, stats: &BTreeMap<String, f64>) {
        let names: Vec<_> = stats.keys().cloned().collect();
        if !names.is_empty() {
            write_stdout(&self.colors.blue("Stats: \n"));
        }
        for name in names {
            let value = stats[&name];
            let rendered = if value.fract() == 0.0 {
                format!("{}", value as i64)
            } else {
                value.to_string()
            };
            write_stdout(&format!("{name}: {rendered}\n"));
        }
    }

    fn dry_banner(&self) {
        write_stdout(&self.colors.green("Running in dry mode, no files will be written! \n"));
    }
}

fn options_to_json(options: &BTreeMap<String, Value>) -> Value {
    Value::Object(options.clone().into_iter().collect())
}

fn download_transform(url: &str) -> io::Result<PathBuf> {
    let ext = Path::new(url)
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or("");
    let postfix = if ext.is_empty() {
        String::new()
    } else {
        format!(".{ext}")
    };
    let unique = format!(
        "{}{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0)
    );
    let path = std::env::temp_dir().join(format!("jscodeshift{unique}{postfix}"));
    let status = Command::new("curl")
        .args(["-fsSL", "-o"])
        .arg(&path)
        .arg(url)
        .status()?;
    if !status.success() {
        return Err(io::Error::other(format!(
            "failed to download transform {url}"
        )));
    }
    Ok(path)
}

pub fn run(opts: RunOptions) -> io::Result<i32> {
    let logger = Logger::new();
    let available = available_cpus();
    let cpus = match number_opt(&opts.options, "cpus") {
        Some(n) if n > 0.0 => (n as usize).min(available),
        _ => available,
    };

    let extensions: Option<Vec<String>> = string_opt(&opts.options, "extensions").and_then(|s| {
        if s.is_empty() {
            None
        } else {
            Some(s.split(',').map(|ext| format!(".{ext}")).collect())
        }
    });

    let mut ignores = IgnoreMatcher::new();
    ignores.add(string_list(&opts.options, "ignoreSet"));
    ignores.add(string_list(&opts.options, "ignorePattern"));
    let ignore_configs = string_list(&opts.options, "ignoreConfig");
    if !ignore_configs.is_empty() {
        ignores.add_from_file(&ignore_configs)?;
    }
    if bool_opt(&opts.options, "gitignore", false) {
        let gitignore = std::env::current_dir()?.join(".gitignore");
        ignores.add_from_file([gitignore])?;
    }

    let transform_file = if opts.transform.starts_with("http") {
        match download_transform(&opts.transform) {
            Ok(p) => p,
            Err(e) => {
                write_stderr(&format!("{e}\n"));
                return Ok(1);
            }
        }
    } else {
        PathBuf::from(&opts.transform)
    };

    if !transform_file.exists() {
        logger.missing_transform(&transform_file.display().to_string());
        return Ok(0);
    }

    transform(
        &logger,
        &transform_file,
        &opts.paths,
        &opts.options,
        cpus,
        extensions.as_deref(),
        &ignores,
    )
}

fn transform(
    logger: &Logger,
    transform_file: &Path,
    paths: &[String],
    options: &BTreeMap<String, Value>,
    cpus: usize,
    extensions: Option<&[String]>,
    ignores: &IgnoreMatcher,
) -> io::Result<i32> {
    let start = Instant::now();
    let files = get_all_files(paths, extensions, ignores)?;
    let silent = bool_opt(options, "silent", false);
    let run_in_band = bool_opt(options, "runInBand", false);
    let dry = bool_opt(options, "dry", false);
    let verbose = number_opt(options, "verbose").unwrap_or(0.0) as i64;
    let fail_on_error = bool_opt(options, "failOnError", false);
    let use_babel = bool_opt(options, "babel", true);

    if files.is_empty() {
        write_stdout("No files selected, nothing to do. \n");
        return finish(logger, start, &FileCounters::default(), &BTreeMap::new(), silent, fail_on_error);
    }

    let num_files = files.len();
    let processes = if run_in_band { 1 } else { num_files.min(cpus) };
    let chunk_size = if processes > 1 {
        ((num_files + processes - 1) / processes).min(CHUNK_SIZE)
    } else {
        num_files
    };

    if !silent {
        write_stdout(&format!("Processing {num_files} files... \n"));
        if !run_in_band {
            write_stdout(&format!("Spawning {processes} workers...\n"));
        }
        if dry {
            logger.dry_banner();
        }
    }

    let package_root = package_root();
    let host = package_root.join("bridge").join("transform-host.js");
    if !host.exists() {
        return Err(io::Error::new(
            io::ErrorKind::NotFound,
            format!("missing transform host {}", host.display()),
        ));
    }

    let options_json = options_to_json(options);
    let next_index = Arc::new(Mutex::new(0usize));
    let files = Arc::new(files);
    let counters = Arc::new(Mutex::new(FileCounters::default()));
    let stats = Arc::new(Mutex::new(BTreeMap::<String, f64>::new()));

    let next = {
        let files = Arc::clone(&files);
        let next_index = Arc::clone(&next_index);
        let silent = silent;
        let run_in_band = run_in_band;
        move || -> Vec<String> {
            let mut index = next_index.lock().expect("next index");
            if !silent && !run_in_band && *index < files.len() {
                let n = chunk_size.min(files.len() - *index);
                write_stdout(&format!("Sending {n} files to free worker...\n"));
            }
            let start = *index;
            let end = (start + chunk_size).min(files.len());
            *index = end;
            files[start..end].to_vec()
        }
    };

    let mut handles = Vec::new();
    for _ in 0..processes {
        let mut worker = Worker::spawn(&host, &transform_file.to_string_lossy(), use_babel, &package_root)?;
        let next = next.clone();
        let options_json = options_json.clone();
        let counters = Arc::clone(&counters);
        let stats = Arc::clone(&stats);
        let verbose = verbose;
        // Logger is cheap (just color flag)
        let colors_ok = logger.colors;
        handles.push(std::thread::spawn(move || {
            let logger = ThreadLogger { colors: colors_ok };
            loop {
                let chunk = next();
                if let Err(e) = worker.send_job(&chunk, &options_json) {
                    write_stderr(&format!("{e}\n"));
                    break;
                }
                if chunk.is_empty() {
                    let _ = worker.wait();
                    break;
                }
                loop {
                    match worker.recv() {
                        Ok(Some(WorkerMessage::Status { status, msg })) => {
                            {
                                let mut c = counters.lock().expect("counters");
                                match status.as_str() {
                                    "error" => c.error += 1,
                                    "ok" => c.ok += 1,
                                    "nochange" => c.nochange += 1,
                                    "skip" => c.skip += 1,
                                    _ => {}
                                }
                            }
                            logger.status(&status, &line_break(&msg), verbose);
                        }
                        Ok(Some(WorkerMessage::Update { name, quantity })) => {
                            let mut s = stats.lock().expect("stats");
                            *s.entry(name).or_insert(0.0) += quantity;
                        }
                        Ok(Some(WorkerMessage::Free)) => break,
                        Ok(Some(WorkerMessage::Report { file, msg })) => {
                            logger.report(&file, &msg);
                        }
                        Ok(Some(WorkerMessage::Print { text })) => {
                            write_stdout(&format!("{text}\n"));
                        }
                        Ok(None) => return,
                        Err(e) => {
                            write_stderr(&format!("{e}\n"));
                            return;
                        }
                    }
                }
            }
        }));
    }

    for handle in handles {
        let _ = handle.join();
    }

    let counters = counters.lock().expect("counters").clone();
    let stats = stats.lock().expect("stats").clone();
    finish(logger, start, &counters, &stats, silent, fail_on_error)
}

struct ThreadLogger {
    colors: Colors,
}

impl ThreadLogger {
    fn status(&self, status: &str, msg: &str, verbose: i64) {
        match status {
            "ok" if verbose >= 2 => write_stdout(&format!(
                "{}{msg}",
                self.colors.bg_green(&self.colors.white(" OKK "))
            )),
            "nochange" if verbose >= 1 => write_stdout(&format!(
                "{}{msg}",
                self.colors.bg_yellow(&self.colors.white(" NOC "))
            )),
            "skip" if verbose >= 1 => write_stdout(&format!(
                "{}{msg}",
                self.colors.bg_yellow(&self.colors.white(" SKIP "))
            )),
            "error" if verbose >= 0 => write_stdout(&format!(
                "{}{msg}",
                self.colors.bg_red(&self.colors.white(" ERR "))
            )),
            _ => {}
        }
    }

    fn report(&self, file: &str, msg: &str) {
        write_stdout(&line_break(&format!(
            "{}{file} {msg}",
            self.colors.bg_blue(&self.colors.white(" REP "))
        )));
    }
}

// Colors is Copy
impl Copy for crate::colors::Colors {}

fn finish(
    logger: &Logger,
    start: Instant,
    counters: &FileCounters,
    stats: &BTreeMap<String, f64>,
    silent: bool,
    fail_on_error: bool,
) -> io::Result<i32> {
    let elapsed = start.elapsed().as_secs_f64();
    let time_elapsed = format!("{elapsed:.3}");
    if !silent {
        write_stdout("All done. \n");
        logger.show_file_stats(counters);
        logger.show_stats(stats);
        write_stdout(&format!("Time elapsed: {time_elapsed}seconds \n"));
        if fail_on_error && counters.error > 0 {
            return Ok(1);
        }
    }
    Ok(0)
}
"}

