{"path":"/workspace/rust/main.rs","command":"create","file_text":"//! jscodeshift CLI entry point. Port of `bin/jscodeshift.js`.

use std::io::{self, Read, Write};
use std::path::PathBuf;
use std::process;

use jscodeshift::args::{self, bool_opt, string_opt};
use jscodeshift::runner::{self, RunOptions};

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let parsed = match args::parse(&args) {
        Ok(p) => p,
        Err(e) => {
            let dest: &mut dyn Write = if e.exit_code == 0 {
                &mut io::stdout()
            } else {
                &mut io::stderr()
            };
            let _ = dest.write_all(e.message.as_bytes());
            process::exit(e.exit_code);
        }
    };

    if parsed.positional_arguments.is_empty() && !bool_opt(&parsed.options, "stdin", false) {
        let mut stderr = io::stderr();
        let _ = write!(
            stderr,
            "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
            args::get_help_text()
        );
        process::exit(1);
    }

    let transform = string_opt(&parsed.options, "transform").unwrap_or_else(|| "./transform.js".into());
    let transform = if transform.starts_with("http://") || transform.starts_with("https://") {
        transform
    } else {
        PathBuf::from(&transform)
            .canonicalize()
            .unwrap_or_else(|_| {
                // Match path.resolve which does not require the file to exist.
                let p = if PathBuf::from(&transform).is_absolute() {
                    PathBuf::from(&transform)
                } else {
                    std::env::current_dir()
                        .unwrap_or_else(|_| PathBuf::from("."))
                        .join(&transform)
                };
                // Normalize . and .. without requiring existence.
                normalize_path(&p)
            })
            .to_string_lossy()
            .into_owned()
    };

    let paths = if bool_opt(&parsed.options, "stdin", false) {
        let mut buffer = String::new();
        let _ = io::stdin().read_to_string(&mut buffer);
        buffer.split('\n').map(|s| s.to_string()).collect()
    } else {
        args::positional_strings(&parsed.positional_arguments)
    };

    let code = match runner::run(RunOptions {
        transform,
        paths,
        options: parsed.options,
    }) {
        Ok(code) => code,
        Err(e) => {
            let _ = writeln!(io::stderr(), "{e}");
            1
        }
    };
    process::exit(code);
}

fn normalize_path(path: &std::path::Path) -> PathBuf {
    use std::path::Component;
    let mut out = PathBuf::new();
    for comp in path.components() {
        match comp {
            Component::CurDir => {}
            Component::ParentDir => {
                out.pop();
            }
            other => out.push(other.as_os_str()),
        }
    }
    out
}
"}

{"path":"/workspace/bridge/transform-host.js","command":"create","file_text":"#!/usr/bin/env node
/**
 * Minimal compatibility bridge that loads and executes user transforms.
 *
 * The Rust runner owns argument parsing, file discovery, ignore rules,
 * worker orchestration, stats, and output. This host is the only extra
 * JavaScript module beyond the public package entrypoints: it must stay
 * in JS so existing transforms can `require('jscodeshift')` and use
 * recast/ast-types collections, builders, comments, and parsers.
 */

'use strict';

const path = require('path');
const readline = require('readline');

const root = process.env.JSCODESHIFT_ROOT || path.resolve(__dirname, '..');

// Public package modules must resolve from the package root.
module.paths.unshift(path.join(root, 'node_modules'));
module.paths.unshift(root);

const async = require('neo-async');
const fs = require('graceful-fs');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');
const getParser = require(path.join(root, 'src', 'getParser'));
const jscodeshift = require(path.join(root, 'src', 'core'));

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

let transform;
let parserFromTransform;

function send(data) {
  process.stdout.write(JSON.stringify(data) + '\n');
}

function prepareJscodeshift(options) {
  const parser = parserFromTransform ||
    getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function setup(tr, babel) {
  if (babel === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([
        presetEnv.default,
        {targets: {node: true}},
      ]);
    }
    presets.push(
      /\.tsx?$/.test(tr) ?
        require('@babel/preset-typescript').default :
        require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const loaded = require(tr);
  transform = typeof loaded.default === 'function' ?
    loaded.default :
    loaded;
  if (loaded.parser) {
    parserFromTransform = typeof loaded.parser === 'string' ?
      getParser(loaded.parser) :
      loaded.parser;
  }
}

function updateStatus(status, file, msg) {
  msg = msg ? file + ' ' + msg : file;
  send({action: 'status', status: status, msg: msg});
}

function report(file, msg) {
  send({action: 'report', file, msg});
}

function empty() {}

function stats(name, quantity) {
  quantity = typeof quantity !== 'number' ? 1 : quantity;
  send({action: 'update', name: name, quantity: quantity});
}

function trimStackTrace(trace) {
  if (!trace) {
    return '';
  }
  const lines = trace.split('\n');
  const result = [];
  lines.every(function(line) {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

function run(data) {
  const files = data.files || [];
  const options = data.options || {};
  if (!files.length) {
    send({action: 'free'});
    return;
  }
  async.each(
    files,
    function(file, callback) {
      fs.readFile(file, async function(err, source) {
        if (err) {
          updateStatus('error', file, 'File error: ' + err);
          callback();
          return;
        }
        source = source.toString();
        try {
          const jscodeshiftApi = prepareJscodeshift(options);
          const out = await transform(
            {
              path: file,
              source: source,
            },
            {
              j: jscodeshiftApi,
              jscodeshift: jscodeshiftApi,
              stats: options.dry ? stats : empty,
              report: msg => report(file, msg),
            },
            options
          );
          if (!out || out === source) {
            updateStatus(out ? 'nochange' : 'skip', file);
            callback();
            return;
          }
          if (options.print) {
            send({action: 'print', text: String(out).replace(/\n$/, '') === String(out) ? out : out});
            // Preserve original console.log which adds a trailing newline.
            // The Rust runner reprints the payload plus '\n'. Recast output
            // typically already includes a trailing newline, so strip one
            // trailing newline to avoid a double blank line when we add \n.
            // Original Worker used console.log(out) which prints out + '\n'.
            // If out already ends with \n, console.log adds another.
            // We send the exact `out` and let Rust print `${text}\n`.
          }
          if (!options.dry) {
            writeFileAtomic(file, out, function(err) {
              if (err) {
                updateStatus('error', file, 'File writer error: ' + err);
              } else {
                updateStatus('ok', file);
              }
              callback();
            });
          } else {
            updateStatus('ok', file);
            callback();
          }
        } catch(err) {
          updateStatus(
            'error',
            file,
            'Transformation error ('+ err.message.replace(/\n/g, ' ') + ')\n' + trimStackTrace(err.stack)
          );
          callback();
        }
      });
    },
    function(err) {
      if (err) {
        updateStatus('error', '', 'This should never be shown!');
      }
      send({action: 'free'});
    }
  );
}

setup(process.argv[2], process.argv[3]);

const rl = readline.createInterface({
  input: process.stdin,
  crlfDelay: Infinity,
});

rl.on('line', (line) => {
  if (!line) {
    return;
  }
  let data;
  try {
    data = JSON.parse(line);
  } catch (e) {
    updateStatus('error', '', String(e));
    send({action: 'free'});
    return;
  }
  run(data);
});

rl.on('close', () => {
  process.exit(0);
