/**
 * Compatibility launcher. The CLI implementation lives in the Rust binary;
 * this script preserves the public `bin` entrypoint.
 */

'use strict';

const {spawnSync} = require('child_process');
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const candidates = [
  process.env.JSCODESHIFT_BIN,
  path.join(root, 'target', 'release', 'jscodeshift'),
  path.join(root, 'target', 'debug', 'jscodeshift'),
].filter(Boolean);

let bin = null;
for (const candidate of candidates) {
  try {
    fs.accessSync(candidate, fs.constants.X_OK);
    bin = candidate;
    break;
  } catch (_) {}
}

if (!bin) {
  process.stderr.write(
    'jscodeshift: rust binary not found. Run app-setup/build.sh first.\n'
  );
  process.exit(1);
}

const result = spawnSync(bin, process.argv.slice(2), {
  stdio: 'inherit',
});

if (result.error) {
  process.stderr.write(String(result.error) + '\n');
  process.exit(1);
}

process.exit(result.status === null ? 1 : result.status);
