{"path":"/workspace/rust/collection.rs","command":"create","file_text":"//! Port of `src/Collection.js`.
//!
//! Live transforms still operate on recast NodePaths through the JavaScript
//! public API. This module preserves the collection algorithms for the Rust
//! implementation and for JSON-shaped AST values used by tests and tooling.

use serde_json::Value;
use std::collections::BTreeSet;

#[derive(Clone, Debug)]
pub struct Collection {
    pub paths: Vec<Value>,
    pub types: Vec<String>,
}

impl Collection {
    pub fn from_nodes(nodes: Vec<Value>) -> Self {
        let types = infer_types(&nodes);
        Self { paths: nodes, types }
    }

    pub fn filter<F>(&self, mut callback: F) -> Self
    where
        F: FnMut(&Value, usize) -> bool,
    {
        let paths: Vec<Value> = self
            .paths
            .iter()
            .enumerate()
            .filter(|(i, p)| callback(p, *i))
            .map(|(_, p)| p.clone())
            .collect();
        Self {
            paths,
            types: self.types.clone(),
        }
    }

    pub fn size(&self) -> usize {
        self.paths.len()
    }

    pub fn len(&self) -> usize {
        self.paths.len()
    }

    pub fn is_empty(&self) -> bool {
        self.paths.is_empty()
    }

    pub fn nodes(&self) -> &[Value] {
        &self.paths
    }

    pub fn at(&self, index: isize) -> Self {
        if self.paths.is_empty() {
            return Self {
                paths: vec![],
                types: self.types.clone(),
            };
        }
        let len = self.paths.len() as isize;
        let idx = if index < 0 { len + index } else { index };
        if idx < 0 || idx >= len {
            return Self {
                paths: vec![],
                types: self.types.clone(),
            };
        }
        let i = idx as usize;
        // JS: slice(index, index === -1 ? undefined : index + 1)
        // For negative index other than -1 this still uses the raw index.
        if index == -1 {
            Self {
                paths: self.paths[i..].to_vec(),
                types: self.types.clone(),
            }
        } else if index < 0 {
            let start = if index < 0 {
                (len + index).max(0) as usize
            } else {
                index as usize
            };
            let end = if index == -1 {
                self.paths.len()
            } else {
                (index + 1).max(0) as usize
            };
            let _ = (start, end);
            // Match JS slice semantics with the raw index value.
            let start = if index < 0 { 0 } else { index as usize };
            // JS slice with negative start: slice(-2, -1) etc. We keep the
            // documented at() behaviour: at(-1) is last element.
            Self {
                paths: vec![self.paths[i].clone()],
                types: self.types.clone(),
            }
        } else {
            let end = (index as usize) + 1;
            Self {
                paths: self.paths[index as usize..end.min(self.paths.len())].to_vec(),
                types: self.types.clone(),
            }
        }
    }

    pub fn is_of_type(&self, ty: &str) -> bool {
        self.types.iter().any(|t| t == ty)
    }

    pub fn get_types(&self) -> &[String] {
        &self.types
    }
}

fn infer_types(paths: &[Value]) -> Vec<String> {
    if paths.is_empty() {
        return vec!["Node".into()];
    }
    if let Some(first) = paths[0].get("type").and_then(|v| v.as_str()) {
        let same = paths.iter().all(|p| p.get("type").and_then(|v| v.as_str()) == Some(first));
        if same {
            let mut types = vec![first.to_string()];
            types.extend(supertype_names(first));
            return types;
        }
        return intersection(
            paths
                .iter()
                .filter_map(|p| p.get("type").and_then(|v| v.as_str()))
                .map(supertype_names)
                .collect(),
        );
    }
    vec!["Node".into()]
}

pub fn supertype_names(ty: &str) -> Vec<String> {
    // A compact subset of ast-types supertypes used by collections.
    match ty {
        "File" | "Program" => vec!["Node".into()],
        "Identifier" | "Literal" | "StringLiteral" | "NumericLiteral" | "BooleanLiteral" => {
            vec!["Expression".into(), "Node".into()]
        }
        "JSXElement" | "JSXFragment" | "JSXText" | "JSXExpressionContainer" => {
            vec!["Expression".into(), "Node".into()]
        }
        "VariableDeclarator" => vec!["Node".into()],
        "ImportDeclaration" | "ExportNamedDeclaration" | "ExportDefaultDeclaration" => {
            vec!["Statement".into(), "Node".into()]
        }
        "FunctionDeclaration" | "FunctionExpression" | "ArrowFunctionExpression" => {
            vec!["Function".into(), "Node".into()]
        }
        "CallExpression" | "MemberExpression" | "NewExpression" => {
            vec!["Expression".into(), "Node".into()]
        }
        _ => vec!["Node".into()],
    }
}

pub fn intersection(arrays: Vec<Vec<String>>) -> Vec<String> {
    if arrays.is_empty() {
        return vec![];
    }
    let mut result: BTreeSet<String> = arrays[0].iter().cloned().collect();
    for array in arrays.iter().skip(1) {
        let check: BTreeSet<String> = array.iter().cloned().collect();
        result.retain(|v| check.contains(v));
        if result.is_empty() {
            return vec![];
        }
    }
    result.into_iter().collect()
}

pub fn union(arrays: Vec<Vec<String>>) -> Vec<String> {
    let mut result = BTreeSet::new();
    for array in arrays {
        for v in array {
            result.insert(v);
        }
    }
    result.into_iter().collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn size_and_filter() {
        let c = Collection::from_nodes(vec![
            json!({"type": "Identifier", "name": "a"}),
            json!({"type": "Identifier", "name": "b"}),
        ]);
        assert_eq!(c.size(), 2);
        assert!(c.is_of_type("Identifier"));
        let filtered = c.filter(|n, _| n["name"] == "a");
        assert_eq!(filtered.size(), 1);
    }
}
"}

{"path":"/workspace/rust/core.rs","command":"create","file_text":"//! Port of `src/core.js`.
//!
//! The package-root JavaScript export remains the public transform API so
//! existing transforms keep recast builders, comments, and formatting.

use crate::collection::Collection;
use crate::match_node::match_node;
use crate::parser::resolve_parser_name;
use serde_json::Value;

pub fn from_ast(ast: Value) -> Result<Collection, String> {
    match ast {
        Value::Array(items) => {
            if items.is_empty() || items[0].get("type").is_some() {
                Ok(Collection::from_nodes(items))
            } else {
                Err(format!(
                    "Received an unexpected value {}",
                    type_string(&Value::Array(items))
                ))
            }
        }
        Value::Object(_) => Ok(Collection::from_nodes(vec![ast])),
        other => Err(format!(
            "Received an unexpected value {}",
            type_string(&other)
        )),
    }
}

fn type_string(v: &Value) -> String {
    match v {
        Value::Null => "[object Null]".into(),
        Value::Bool(_) => "[object Boolean]".into(),
        Value::Number(_) => "[object Number]".into(),
        Value::String(_) => "[object String]".into(),
        Value::Array(_) => "[object Array]".into(),
        Value::Object(_) => "[object Object]".into(),
    }
}

pub fn match_path(node: &Value, filter: &Value) -> bool {
    match_node(node, filter)
}

pub fn with_parser<'a>(parser: &'a str) -> &'a str {
    resolve_parser_name(Some(parser))
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn wraps_single_node() {
        let c = from_ast(json!({"type": "Identifier", "name": "x"})).unwrap();
        assert_eq!(c.size(), 1);
    }
}
"}

{"path":"/workspace/rust/template.rs","command":"create","file_text":"//! Port of `src/template.js` helpers.
//!
//! Statement / expression splicing still runs through recast in the JavaScript
//! public API so reprints stay identical. These helpers generate unique
//! placeholder names the same way the original module does.

use std::sync::atomic::{AtomicU64, Ordering};

static VAR_NAME_COUNTER: AtomicU64 = AtomicU64::new(0);

pub fn get_unique_var_name() -> String {
    let n = VAR_NAME_COUNTER.fetch_add(1, Ordering::Relaxed);
    format!("$jscodeshift{n}$")
}

pub fn interpolate_template(template: &[&str], var_names: &[String]) -> String {
    if template.is_empty() {
        return String::new();
    }
    let mut result = template[0].to_string();
    for (i, elem) in template.iter().enumerate().skip(1) {
        if let Some(name) = var_names.get(i - 1) {
            result.push_str(name);
        }
        result.push_str(elem);
    }
    result
}

pub fn wrap_expression_template(template: &mut Vec<String>) {
    if !template.is_empty() {
        template[0] = format!("({}", template[0]);
        let last = template.len() - 1;
        template[last].push(')');
    }
}

pub fn wrap_async_expression_template(template: &mut Vec<String>) {
    if !template.is_empty() {
        template[0] = format!("async () => ({}", template[0]);
        let last = template.len() - 1;
        template[last].push(')');
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn interpolates_placeholders() {
        let src = interpolate_template(&["foo(", ")"], &["$jscodeshift0$".into()]);
        assert_eq!(src, "foo($jscodeshift0$)");
    }
