{"path":"/workspace/rust/collections.rs","command":"create","file_text":"//! Ports of `src/collections/*`.
//!
//! Method registration still happens in the JavaScript public API so user
//! transforms observe the original recast typed collections.

use crate::match_node::match_node;
use serde_json::Value;

pub fn jsx_name_filter(name: &str) -> Value {
    serde_json::json!({
        "openingElement": { "name": { "name": name } }
    })
}

pub fn variable_declarator_filter(name: Option<&str>) -> Option<Value> {
    name.map(|n| serde_json::json!({ "id": { "name": n } }))
}

pub fn import_source_filter(source_path: &str) -> Value {
    serde_json::json!({ "source": { "value": source_path } })
}

pub fn jsx_has_child_named(node: &Value, name: &str) -> bool {
    node.get("type").and_then(|t| t.as_str()) == Some("JSXElement")
        && node
            .get("children")
            .and_then(|c| c.as_array())
            .map(|children| {
                children.iter().any(|child| {
                    child.get("type").and_then(|t| t.as_str()) == Some("JSXElement")
                        && child
                            .pointer("/openingElement/name/name")
                            .and_then(|v| v.as_str())
                            == Some(name)
                })
            })
            .unwrap_or(false)
}

pub fn is_require_of(node: &Value, names: &[&str]) -> bool {
    if node.get("type").and_then(|t| t.as_str()) != Some("VariableDeclarator") {
        return false;
    }
    let init = match node.get("init") {
        Some(v) => v,
        None => return false,
    };
    if init.get("type").and_then(|t| t.as_str()) != Some("CallExpression") {
        return false;
    }
    let callee_ok = init.pointer("/callee/name").and_then(|v| v.as_str()) == Some("require");
    if !callee_ok {
        return false;
    }
    if names.is_empty() {
        return true;
    }
    names.iter().any(|n| {
        init.pointer("/arguments/0")
            .map(|arg| {
                match_node(arg, &serde_json::json!({"type": "Literal", "value": n}))
                    || match_node(arg, &serde_json::json!({"type": "StringLiteral", "value": n}))
            })
            .unwrap_or(false)
    })
}

pub fn jsx_root_name(opening_name: &Value) -> Option<String> {
    let mut name = opening_name;
    while name.get("type").and_then(|t| t.as_str()) == Some("JSXMemberExpression") {
        name = name.get("object")?;
    }
    name.get("name")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn detects_require() {
        let node = json!({
            "type": "VariableDeclarator",
            "id": {"type": "Identifier", "name": "Foo"},
            "init": {
                "type": "CallExpression",
                "callee": {"type": "Identifier", "name": "require"},
                "arguments": [{"type": "Literal", "value": "mod"}]
            }
        });
        assert!(is_require_of(&node, &["mod"]));
        assert!(!is_require_of(&node, &["other"]));
    }
}
"}

