{"path":"/workspace/rust/once.rs","command":"create","file_text":"//! Port of `src/utils/once.js`.

use std::sync::OnceLock;

pub struct Once<T> {
    cell: OnceLock<T>,
}

impl<T> Once<T> {
    pub const fn new() -> Self {
        Self {
            cell: OnceLock::new(),
        }
    }

    pub fn call<F>(&self, func: F) -> &T
    where
        F: FnOnce() -> T,
    {
        self.cell.get_or_init(func)
    }
}

impl<T> Default for Once<T> {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicUsize, Ordering};

    #[test]
    fn runs_only_once() {
        let once = Once::new();
        let n = AtomicUsize::new(0);
        once.call(|| n.fetch_add(1, Ordering::SeqCst));
        once.call(|| n.fetch_add(1, Ordering::SeqCst));
        assert_eq!(n.load(Ordering::SeqCst), 1);
    }
}
"}

