{"path":"/workspace/rust/get_parser.rs","command":"create","file_text":"//! Port of `src/getParser.js`.

use crate::parser::{
    babel5_compat_options, babylon_default_options, flow_default_options, resolve_parser_name,
    ts_options,
};
use serde_json::{json, Value};

pub fn get_parser(parser_name: Option<&str>, options: Option<Value>) -> Value {
    match resolve_parser_name(parser_name) {
        "babylon" => json!({
            "name": "babylon",
            "options": options.unwrap_or_else(babylon_default_options),
        }),
        "flow" => json!({
            "name": "flow",
            "options": options.unwrap_or_else(flow_default_options),
        }),
        "ts" => json!({
            "name": "ts",
            "options": ts_options(),
        }),
        "tsx" => {
            let mut opts = ts_options();
            if let Some(plugins) = opts.get_mut("plugins").and_then(|p| p.as_array_mut()) {
                plugins.insert(0, Value::String("jsx".into()));
            }
            json!({
                "name": "tsx",
                "options": opts,
            })
        }
        _ => json!({
            "name": "babel",
            "options": babel5_compat_options(),
        }),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn defaults_to_babel() {
        let p = get_parser(None, None);
        assert_eq!(p["name"], "babel");
        assert!(p["options"]["plugins"]
            .as_array()
            .unwrap()
            .iter()
            .any(|v| v == "estree"));
    }

    #[test]
    fn tsx_includes_jsx() {
        let p = get_parser(Some("tsx"), None);
        let plugins = p["options"]["plugins"].as_array().unwrap();
        assert_eq!(plugins[0], "jsx");
        assert!(plugins.iter().any(|v| v == "typescript"));
    }
}
"}

